<script lang="ts">
 import {onMount} from 'svelte';import * as api from '../../bindings';import type {CaseOperations} from '../operations/controller.svelte';import ResourcePanel from '../resources/ResourcePanel.svelte';import EvidencePicker from '../pickers/EvidencePicker.svelte';import ErrorNotice from '../../ErrorNotice.svelte';
 let {generation,operations,active,onopen,onCandidate,onReport}:{generation:number;operations:CaseOperations;active:boolean;onopen:(kind:string,id:string)=>void;onCandidate:(s:api.AiSuggestionView)=>void;onReport:(s:api.AiSuggestionView)=>void}=$props();
 let endpoint=$state('http://127.0.0.1:11434/'),status=$state<api.AiStatusView|null>(null),model=$state('kokin-qwen3-4b-q4km'),task=$state('cited_summary'),consent=$state(false),sources=$state<api.GroundingInput[]>([]),page=$state<api.AiPageView|null>(null),offset=$state(0),error=$state<api.CommandError|null>(null),busy=$state(false),reason=$state(''),selected=$state<string|null>(null),semantic=$state<api.SemanticStatusView|null>(null);let live=true;let installJob=$state<api.ResourceJobView|null>(null);
 $effect(()=>{endpoint;model;task;sources;consent=false;});
 onMount(()=>{void refresh();return()=>{live=false;sources=[];consent=false;};});
 export async function refresh(){try{const [rows,index]=await Promise.all([api.aiPage(generation,offset),api.semanticStatus(generation)]);if(live){page=rows;semantic=index;}}catch(raw){if(live)error=api.asCommandError(raw);}}
 async function connect(){busy=true;error=null;try{const value=await api.aiStatus(endpoint);if(live)status=value;}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live)busy=false;}}
 async function generate(){if(!consent||!sources.length)return;await operations.run('ai_generate',{version:1,endpoint,model,task,observation_ids:sources.map(s=>s.id),consent});await refresh();}
 async function installModel(){busy=true;error=null;try{const job=await api.aiModelInstall({version:1,model,endpoint,consent:true});let result=await api.resourceStatus(job);while(live&&result.status==='running'){installJob=result;await new Promise(r=>setTimeout(r,300));result=await api.resourceStatus(job);}if(!live)return;installJob=result;if(result.status!=='completed')throw new Error(result.error??'Local model import did not complete');await connect();}catch(raw){if(live)error=api.asCommandError(raw);}finally{if(live)busy=false;}}

 async function review(id:string,decision:string){error=null;try{await api.aiReview(generation,{id,decision,rationale:reason});if(live){reason='';selected=null;await refresh();}}catch(raw){if(live)error=api.asCommandError(raw);}}
</script>
<section class="ai-workspace" aria-label="Local AI" hidden={!active}><header><h2>Local AI</h2><p>Cited suggestions for human review. All seven confidence dimensions and analytical decisions remain in the existing record forms.</p></header>
 {#if error}<ErrorNotice {error}/>{/if}
 <details open><summary>Local inference setup</summary><label>Ollama loopback endpoint<input bind:value={endpoint}/></label><p>Ollama is optional and separately installed. “Check local runtime” sends model-list requests only to this literal loopback endpoint. It sends no case evidence or request to a cloud provider.</p><button type="button" disabled={busy} onclick={connect}>Check local runtime</button>
 {#if status}<p role="status">{status.ollama_status}</p><dl><dt>Hardware</dt><dd>{status.architecture} · {status.cpu_threads} CPU threads · {status.memory_kind}</dd><dt>Memory</dt><dd>{status.available_memory_bytes===null?'Unavailable':`${(status.available_memory_bytes/1024**3).toFixed(1)} GiB available estimate`} / {status.total_memory_bytes===null?'unknown total':`${(status.total_memory_bytes/1024**3).toFixed(1)} GiB total`}</dd><dt>Runtime</dt><dd>{status.accelerator_status}</dd></dl><p>{status.recommendation?`Measured Balanced recommendation: ${status.recommendation}.`:"No measured Balanced recommendation yet."} Balanced, Faster, and Higher quality recommendations require measured synthetic-task quality and latency on this machine. No unmeasured recommendation or silent larger-model download.</p>{#each status.models as m}<p>{m.name}: {m.reviewed_artifact?'reviewed local artifact':'not eligible for inference; import a reviewed artifact'} · {(m.bytes/1024**3).toFixed(2)} GiB</p>{/each}<details><summary>Loaded-model memory and context</summary><pre>{JSON.stringify(status.loaded_models,null,2)}</pre></details>{/if}
 <button type="button" disabled={operations.busy||!status?.models.some(m=>m.reviewed_artifact)} onclick={async()=>{await operations.run("ai_benchmark",{endpoint});await connect();}}>Benchmark reviewed models with synthetic evidence</button>
 {#if status}<div class="toolbar">{#each [['Balanced',status.recommendation],['Faster',status.faster],['Higher quality',status.higher_quality]] as [title,choice]}<button type="button" disabled={!choice} onclick={()=>{if(choice)model=choice;}}>{title}{choice?`: ${choice}`:' — unmeasured/unavailable'}</button>{/each}</div><p>Profiles recheck installed artifact identity, this machine's measurements, and a 6 GiB memory reserve. Higher quality may exceed Balanced's 30-second target. Choosing a profile never installs a resource.</p>{/if}<label>Reviewed model<select bind:value={model}><option value="kokin-qwen3-4b-q4km">Qwen3 4B Q4_K_M</option><option value="kokin-qwen3-8b-q4km">Qwen3 8B Q4_K_M</option><option value="kokin-qwen3-14b-q4km">Qwen3 14B Q4_K_M</option></select></label><p>After installing its reviewed GGUF resource below, upload it locally into Ollama. This never uses Ollama’s remote pull path.</p><button type="button" disabled={busy||!status?.ollama_status.startsWith('available')} onclick={installModel}>Import verified resource into local Ollama</button>{#if installJob}<p role="status">Local model import: {installJob.status} · {installJob.stage}. It contains model weights only and can continue after a case closes.</p>{#if installJob.status==='running'}<button type="button" onclick={()=>api.resourceCancel(installJob!.operation_id).catch(raw=>error=api.asCommandError(raw))}>Cancel local model import</button>{/if}{/if}</details>
 <ResourcePanel/>
 <section><h3>Semantic search</h3>{#if semantic}<p>{semantic.indexed} / {semantic.observations} observations indexed. {semantic.quality_gate?'Synthetic retrieval gate passed.':'Semantic/hybrid modes remain unavailable until the retrieval gate passes.'}</p><p>{semantic.limitation}</p>{/if}<button type="button" disabled={operations.busy||!semantic?.resources_present} onclick={async()=>{await operations.run('embedding_rebuild',{});await refresh();}}>Rebuild encrypted semantic index</button><button type="button" onclick={refresh}>Refresh AI and index status</button></section>
 <section><h3>Ask about selected evidence</h3><label>Task<select bind:value={task}><option value="cited_summary">Cited summary</option><option value="entity_candidate">Entity candidates</option><option value="relationship_candidate">Relationship candidates</option></select></label><EvidencePicker onchoose={citation=>{if(!sources.some(c=>c.id===citation.id)&&sources.length<24)sources=[...sources,citation];}} oninspect={onopen}/><ul>{#each sources as citation}<li><button type="button" onclick={()=>onopen('observation',citation.id)}>Inspect selected observation</button> {citation.id}<button type="button" onclick={()=>sources=sources.filter(c=>c.id!==citation.id)}>Remove</button></li>{/each}</ul><label class="check"><input type="checkbox" bind:checked={consent}/>Send only these verified observation IDs and text to the selected local model for this task. Model output stays a suggestion and has no analytical tools.</label><button type="button" disabled={operations.busy||!consent||!sources.length||!status?.models.some(m=>m.name===model&&m.reviewed_artifact)} onclick={generate}>Generate cited suggestions</button></section>
 <section><h3>Suggestions and review</h3>{#if page}{#each page.rows as s}<article><h4>{s.kind.replaceAll('_',' ')} · {s.review??'awaiting human review'}</h4><p>{s.text}</p>{#if s.review_rationale}<p>Human review ({s.review_actor}, {s.review_utc}): {s.review_rationale}</p>{/if}<p class="by">{s.model} · {s.created_utc}</p><div class="toolbar">{#each s.cited_observation_ids as oid}<button type="button" onclick={()=>onopen('observation',oid)}>Inspect cited observation</button>{/each}<button type="button" onclick={()=>{selected=s.id;reason='';}}>Review suggestion</button>{#if s.review==='reviewed'}{#if s.kind==='cited_summary'}<button type="button" onclick={()=>onReport(s)}>Use in report draft</button>{:else}<button type="button" onclick={()=>onCandidate(s)}>Open human decision form</button>{/if}{/if}</div>{#if selected===s.id}<label>Review explanation<textarea bind:value={reason} required></textarea></label><button type="button" disabled={!reason.trim()} onclick={()=>review(s.id,'reviewed')}>Mark reviewed; create no facts</button><button type="button" disabled={!reason.trim()} onclick={()=>review(s.id,'rejected')}>Reject suggestion</button>{/if}</article>{/each}<p>{page.total} stored suggestions. Reviewing a candidate does not create a record or accept a relationship.</p><button type="button" disabled={offset===0} onclick={()=>{offset-=50;void refresh();}}>Previous suggestions</button><button type="button" disabled={offset+50>=page.total} onclick={()=>{offset+=50;void refresh();}}>Next suggestions</button>{/if}</section>
</section>
<style>.ai-workspace{min-width:0}header p,p{color:var(--foreground-secondary);line-height:1.6;max-width:80ch}h2{font-size:28px}h3{font-size:20px}section+section,details{margin:24px 0}details{border:1px solid var(--border);padding:20px;border-radius:var(--radius-panel)}summary{font-weight:600;cursor:pointer;margin-bottom:16px}label{display:grid;gap:8px;margin:12px 0}.check{display:flex;align-items:start;line-height:1.6}input,textarea,select{box-sizing:border-box;max-width:100%}textarea{min-height:90px}dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:8px}dd{margin:0;overflow-wrap:anywhere}.toolbar{display:flex;gap:8px;flex-wrap:wrap}article{border:1px solid var(--border);padding:20px;margin:16px 0;border-radius:var(--radius-panel)}.by{font-size:12px}li{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style>
